let currentPage=parseInt(location.pathname.split("/").pop(),10)||0;const totalPages=parseInt(document.getElementById("totalPages").textContent,10);function changePage(page){if(isNaN(page)||page<0){console.error("Invalid page number. Page must be a positive number.");return}
if(page>=totalPages)page=totalPages-1;const currentPathParts=location.pathname.split("/");const isPropertiesPath=currentPathParts.includes("properties");let newPath=isPropertiesPath?`/properties/${page}${location.search}`:`${currentPathParts.slice(0, -1).join("/")}/${page}${location.search}`;location.href=newPath}
function updatePageValue(event){if(event.key==="Enter"){const inputPage=parseInt(event.target.value,10)-1;if(isNaN(inputPage)||inputPage<0){alert("Please enter a valid positive page number.");event.target.value=currentPage+1;return}
changePage(inputPage)}}
document.getElementById("currentPageInput").value=currentPage+1